<?php require '../config.php';require_admin();$adminPage=true;$pageTitle='Quản lý đơn hàng';$statuses=['Chờ xác nhận','Đã xác nhận','Đang giao','Hoàn thành','Đã hủy'];if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['order_id']??0);$status=$_POST['status']??'';if(in_array($status,$statuses,true)){$st=$pdo->prepare('UPDATE orders SET status=? WHERE order_id=?');$st->execute([$status,$id]);header('Location: orders.php?updated=1');exit;}}$orders=$pdo->query('SELECT * FROM orders ORDER BY order_date DESC')->fetchAll();require '../includes/header.php';?><div class="row g-4"><div class="col-md-3"><?php require 'nav.php';?></div><div class="col-md-9"><h1 class="section-title">Quản lý đơn hàng</h1><?php if(isset($_GET['updated'])): ?><div class="alert alert-success">Đã cập nhật trạng thái đơn hàng.</div><?php endif; ?><div class="content-card table-responsive"><table class="table"><thead><tr><th>Mã</th><th>Khách hàng</th><th>Ngày đặt</th><th>Tổng tiền</th><th>Trạng thái</th><th>Cập nhật</th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td>#<?= $o['order_id'] ?></td><td><?= e($o['customer_name']) ?><br><small><?= e($o['phone']) ?></small></td><td><?= e($o['order_date']) ?></td><td><?= money($o['total_amount']) ?></td><td><?= e($o['status']) ?></td><td><form method="post" class="d-flex gap-1"><input type="hidden" name="order_id" value="<?= $o['order_id'] ?>"><select class="form-select form-select-sm" name="status"><?php foreach($statuses as $s): ?><option <?= $o['status']===$s?'selected':'' ?>><?= e($s) ?></option><?php endforeach; ?></select><button class="btn btn-sm btn-red">Lưu</button></form></td></tr><?php endforeach; ?></tbody></table><?php if(!$orders): ?><p>Chưa có đơn hàng.</p><?php endif; ?></div></div></div><?php require '../includes/footer.php';?>
